"""Independently evaluate the saved Safe token reimbursement argument."""
import argparse,hashlib,json,pathlib,re,subprocess
ROOT=pathlib.Path(__file__).resolve().parents[2];BASE=ROOT/'acceptance/contract-analysis-aggregates';image=(BASE/'engine-image.txt').read_text().strip();directory=BASE/'corpus'/('candidate-19-'+image[7:23]);p=argparse.ArgumentParser();p.add_argument('--channel',choices=['source','submitted_source'],default='source');a=p.parse_args()
path=directory/('safe-singleton-'+a.channel+'-output.json');raw=path.read_bytes();result=json.loads(raw);assert result['snapshot']['engine_digest']==image;s=result['sections'];method=next(m for m in s['methods']if m.get('name')=='handlePayment');fund=next(f for f in s['funds']if f['method_id']==method['method_id']and f['kind']=='token_transfer_intent');expression=fund['expanded_amount_expression']
assert re.fullmatch(r'[A-Za-z0-9_\s()+*/?:<>=!%&|\-]+',expression)and set(re.findall(r'[A-Za-z_]\w*',expression))<={'gasUsed','baseGas','gasPrice','uint256'}
js=r"""const fs=require('node:fs'),expression=JSON.parse(fs.readFileSync(0,'utf8')).expression,evaluate=new Function('gasUsed','baseGas','gasPrice','uint256','return '+expression.replace(/\b[0-9]+\b/g,'$&n')),rows=[];for(const gas of[0n,1n,21000n,9007199254740993n])for(const base of[0n,7n])for(const price of[0n,2n,100n]){const expected=(gas+base)*price,actual=evaluate(gas,base,price,v=>BigInt.asUintN(256,v));rows.push({gasUsed:String(gas),baseGas:String(base),gasPrice:String(price),expected:String(expected),actual:String(actual),equal:expected===actual});}process.stdout.write(JSON.stringify(rows));"""
vectors=json.loads(subprocess.check_output(['/home/euripides/.nvm/versions/node/v24.20.0/bin/node','-e',js],input=json.dumps({'expression':expression}).encode()));assert len(vectors)==24
document={'status':'PASS'if all(v['equal']for v in vectors)else'FAIL','image':image,'channel':a.channel,'scope':'exact token reimbursement expression below uint256 overflow; allocator assumptions, target interface and actual token settlement remain unverified',
 'expression':expression,'result_sha256':hashlib.sha256(raw).hexdigest(),'method_id':method['method_id'],'fund_id':fund['fund_id'],'source_memory_version_id':fund.get('source_memory_version_id'),
 'assumptions':fund.get('assumptions',[]),'reference':'(gasUsed+baseGas)*gasPrice','vectors':vectors}
(directory/('token-formula-counterexample'+(''if a.channel=='source'else'-'+a.channel)+'.json')).write_text(json.dumps(document,indent=2));print('P2_AGGREGATE_TOKEN_FORMULA',a.channel,document['status'],len(vectors),flush=True);assert document['status']=='PASS'
